WITH base AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, ROUND(cost * 100, 2) AS cost_adjusted FROM products WHERE brand IS DISTINCT FROM 'Initech') SELECT s.id, s.category, s.brand, s.price, s.cost, s.stock_qty, s.supplier_id, s.cost_adjusted, x.inventory_last_restock, x.inventory_quantity FROM base s JOIN LATERAL (SELECT c.last_restock AS inventory_last_restock, c.quantity AS inventory_quantity FROM inventory c WHERE c.product_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) x ON TRUE;
